import{_ as p,a0 as i,w as r,s,ao as l,I as a,a1 as o,A as e,x as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const U=JSON.parse('{"title":"安装Ubuntu13.10后必做的10件事 | LCTT x X-CMD","titleTemplate":false,"description":"安装Ubuntu13.10后必做的10件事 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安装Ubuntu13.10后必做的10件事 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安装Ubuntu13.10后必做的10件事 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/10 Things To Do After Installing Ubuntu 13.10","title":"安装Ubuntu13.10后必做的10件事","tag":"201311","desc":""},"relativePath":"201311/10 Things To Do After Installing Ubuntu 13.10.md","filePath":"[post].md"}'),b={name:"201311/10 Things To Do After Installing Ubuntu 13.10.md"};function m(d,t,g,h,_,T){const u=i("Link");return r(),s("div",null,[t[14]||(t[14]=l('<h1 id="安装ubuntu13-10后必做的10件事" tabindex="-1">安装Ubuntu13.10后必做的10件事 <a class="header-anchor" href="#安装ubuntu13-10后必做的10件事" aria-label="Permalink to “安装Ubuntu13.10后必做的10件事”">​</a></h1><p><strong>Ubuntu 13.10发布了，而且你已经升级了，然后你想知道现在要做些什么。不要着急，这里有10件安装完Ubuntu 13.10后必做的事。</strong></p><p>我们以前为ubuntu每个版本整理了一个安装后核对表，但是因为新功能的到来以及不断的进步，我们建议的步骤也在不断改变和转换。</p><p>因此，升级到ubuntu 13.10后最好做哪些事情呢？</p><h3 id="_1-加快速度" tabindex="-1">1. 加快速度 <a class="header-anchor" href="#_1-加快速度" aria-label="Permalink to “1. 加快速度”">​</a></h3><p>尽管Ubuntu 13.10相较于之前的发布版包含了较少的面向用户的特征，但是新的Smart scopes服务还是不可错过的。</p><h3 id="_2-使用第三方驱动" tabindex="-1">2. 使用第三方驱动 <a class="header-anchor" href="#_2-使用第三方驱动" aria-label="Permalink to “2. 使用第三方驱动”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/04/drivers.jpg" alt=""></p><p>Ubuntu本身已经支持了大量的硬件。但是虽然免费而又开源的的驱动能力越来越强,在Steam 或 Steam HD video 上玩儿游戏仍会感觉性能差强人意。</p><p>如果是这样，可以 <strong>安装并使用专有驱动</strong> ，它们在Software &amp; Updates （软件和更新）工具中。</p><p>在启动器里打开<em>软件源应用</em> （或者通过系统设置）然后点击进入“其他驱动”选项卡，然后按照屏幕上的提示操作。</p><h3 id="_3-安装ubuntu的影音解码器" tabindex="-1">3. 安装Ubuntu的影音解码器 <a class="header-anchor" href="#_3-安装ubuntu的影音解码器" aria-label="Permalink to “3. 安装Ubuntu的影音解码器”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/10/mus.jpg" alt=""></p><p>由于一个很大的法律问题的纠缠，Ubuntu不能即刻支持很多流行的音频视频格式。这是一项很大的先天缺陷。</p><p>但是安装这些支持所需要的仅仅只是几下点击。在安装过程中只需勾选<em>使用限制格式</em> 框来导入需要的解码器，或者，如果你忘了的话，也可以从Ubuntu软件中心安装所有的多媒体相关工具。</p>',15)),a("ul",null,[a("li",null,[o(u,{href:"https://apps.ubuntu.com/cat/applications/ubuntu-restricted-extras/"},{default:e(()=>[...t[0]||(t[0]=[n("安装第三方解码器",-1)])]),_:1})])]),t[15]||(t[15]=l('<h3 id="_4-建立你的社会生活" tabindex="-1">4.建立你的社会生活### <a class="header-anchor" href="#_4-建立你的社会生活" aria-label="Permalink to “4.建立你的社会生活###”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/04/account-toggles.jpg" alt=""></p><p>Facebook, Twitter, Google Talk, Gmail以及其他的社交账号可以在<em>在线账号</em> 里一起设置。</p><p>只需要添加一个网络然后<strong>决定哪些程序可以使用它</strong>。例如，关掉Empathy，默认启动Google Chat，从Social Lens里过滤FaceBook。</p><p>支持的服务包括Twitter, Google, Yahoo!, Facebook (包括 Facebook Chat), Flickr 以及正在增长的大量其他的应用。</p><h3 id="_5-添加第三方应用" tabindex="-1">5. 添加第三方应用 <a class="header-anchor" href="#_5-添加第三方应用" aria-label="Permalink to “5. 添加第三方应用”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/04/apps.jpg" alt=""></p><p>Ubuntu默认提供了一整套的应用，但是众口难调，如果你不喜欢某个应用，或者发现自己缺少了什么应用，你可以很轻松的找到并添加软件。</p><p>打开Ubuntu软件中心，可以看到成千上万的程序，包括下面这些很流行的选择：</p><ul><li><strong>Dropbox</strong> - 流行，跨平台的云存储服务</li><li><strong>Steam</strong> – 游戏发布平台</li><li><strong>GIMP</strong> – 强大的图像处理软件</li><li><strong>VLC</strong> – 流行的影音软件</li></ul><p>您还可以找到像我们这样列出了丰富的附加软件的网站 - 看看我们的<em>Apps</em>标签你会有一些想法。</p>',11)),a("ul",null,[a("li",null,[o(u,{href:"http://www.omgubuntu.co.uk/category/app"},{default:e(()=>[...t[1]||(t[1]=[n("在OMG上查看Ubuntu App 列表! !",-1)])]),_:1})])]),t[16]||(t[16]=l('<h3 id="_6-保护你的隐私" tabindex="-1">6.保护你的隐私 <a class="header-anchor" href="#_6-保护你的隐私" aria-label="Permalink to “6.保护你的隐私”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/10/priv.jpg" alt=""></p><p>最近隐私问题是一个烫手山芋，因此很高兴看到最新版的Ubuntu改进了它的隐私设置，提供了一个新的界面和大量的新选择。</p><p>不论你是想在启动器上隐藏一个文件还是一个应用，限制从睡眠状态到进入电脑时的访问，或者选择什么样的系统崩溃向Canonical发送信息，在“隐私和安全”面板总是可以提供你想要的工具。</p><h3 id="_7-享受互联网" tabindex="-1">7.享受互联网 <a class="header-anchor" href="#_7-享受互联网" aria-label="Permalink to “7.享受互联网”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/04/gmails.jpg" alt=""></p><p>Canonical宣称在Ubuntu Touch 上，网站可以很容易的打包、整合并用于安装， 以吸引web开发人员。</p><p>该方式已经包含在桌面 Ubuntu 一些版本中。超过300个流行网站-包括Gmail, Yahoo! 和Rd.io-可以和桌面无缝集成。</p><p>例如，添加 GMail， 您可以在启动器和消息菜单上获得喜爱的Gmail选项； 启用Rd.io，您可以使用“声音”（Sound) 菜单控制回放。</p><h3 id="_8-设置自己的unity-yours" tabindex="-1">8. 设置自己的Unity Yours <a class="header-anchor" href="#_8-设置自己的unity-yours" aria-label="Permalink to “8. 设置自己的Unity Yours”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/10/unity_tweak_tool_310.png" alt=""></p><p>Unity比人们想的定制性更好。 <em>Unity Tweak Tool</em> 是一个第三方应用，可以让您调整桌面Unity以打造一个适合您的环境。</p><p>选择包括:</p><ul><li>调整启动器透明度</li><li>设置启动器图标动画</li><li>启动工作台</li><li>设置快捷键</li><li>移动窗口的控制</li></ul><p>但是,不要期望太大，它不会让你移动启动器的。</p>',15)),a("ul",null,[a("li",null,[o(u,{href:"apt:unity-tweak-tool"},{default:e(()=>[...t[2]||(t[2]=[n("从Ubuntu软件中心安装Unity Tweak Tool",-1)])]),_:1})])]),t[17]||(t[17]=l('<h3 id="_9-过滤噪音" tabindex="-1">9. 过滤噪音 <a class="header-anchor" href="#_9-过滤噪音" aria-label="Permalink to “9. 过滤噪音”">​</a></h3><p>Ubuntu’s新的‘Smart Scopes’服务号称要做成一个很方便的工具，但是现在还不像声称的那样智能。</p><p>好消息是这个特性只需一击就可以关闭，所以没有必要因噎废食顺带着排斥Ubuntu。</p><p>如果你每次搜索时还顺带了一堆毫不相关的不知名的音乐结果或者购物建议，你可以单独禁用该范围。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/10/Screen-Shot-2013-10-15-at-11.36.26-750x480.png" alt=""></p><p>如果你发现自己每一个搜索都被无关的音乐结果淹没了，可以禁用“音乐范围”。不想要亚马逊的建议？关掉它。</p><h3 id="_10-传播关于ubuntu13-10的信息" tabindex="-1">10. 传播关于Ubuntu13.10的信息 <a class="header-anchor" href="#_10-传播关于ubuntu13-10的信息" aria-label="Permalink to “10. 传播关于Ubuntu13.10的信息”">​</a></h3><p>我知道，在我们的“应当去做”列表上这是比较尴尬的一项。但是只有人们知道Ubuntu 13.10才会去尝试它，因此请出一份力量，多多分享关于它的新闻。</p><p>无论你是把这篇文章贴到Facebook上，还是为你的OS X粉搭档制作了一个LiveUSB，对于Ubuntu的认知度的提高都是很有帮助的。</p><p>别忘了享受使用它。去检查下Facebook上的简介，听一些音乐，享受一下用Firefox上网。</p><hr>',11)),a("p",null,[t[4]||(t[4]=n("via: ",-1)),o(u,{href:"http://www.omgubuntu.co.uk/2013/10/10-things-installing-ubuntu-13-10"},{default:e(()=>[...t[3]||(t[3]=[n("http://www.omgubuntu.co.uk/2013/10/10-things-installing-ubuntu-13-10",-1)])]),_:1})]),a("p",null,[t[7]||(t[7]=n("译者：",-1)),o(u,{href:"https://github.com/%E8%AF%91%E8%80%85ID"},{default:e(()=>[...t[5]||(t[5]=[n("crowner",-1)])]),_:1}),t[8]||(t[8]=n(" 校对：",-1)),o(u,{href:"https://github.com/jasminepeng"},{default:e(()=>[...t[6]||(t[6]=[n("jasminepeng",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=n("本文由 ",-1)),o(u,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[9]||(t[9]=[n("LCTT",-1)])]),_:1}),t[12]||(t[12]=n(" 原创翻译，",-1)),o(u,{href:"http://linux.cn/"},{default:e(()=>[...t[10]||(t[10]=[n("Linux中国",-1)])]),_:1}),t[13]||(t[13]=n(" 荣誉推出",-1))])])}const k=p(b,[["render",m]]);export{U as __pageData,k as default};
